/* app.css can pull in another sheet; link tags load faster */
@import url("theme.css");

/* Cascade layers decide which group of rules wins */
@layer reset, base, components, utilities;

/* The first layer has the lowest priority */
@layer reset {
  *,
  *::before,
  *::after {
    box-sizing: border-box;
  }
}

/* Type, class and id */
p { line-height: 1.6; }
.card { border-radius: 8px; }
#site-header { position: sticky; top: 0; }

/* Attribute and state */
a[href^="https://"] { text-decoration: underline; }
input:focus-visible { outline: 2px solid #2563eb; }
li:first-child { font-weight: 600; }

/* Combinators: descendant, child, adjacent, general sibling */
nav a { color: #1f2937; }
ul > li { list-style: square; }
h2 + p { margin-top: 4px; }
h2 ~ figure { margin-top: 12px; }

/* Grouping and a universal reset */
h1, h2, h3 { margin-block: 0 0.5em; }
*, *::before, *::after { box-sizing: border-box; }

/* :is() matches any selector in the list */
:is(h1, h2, h3) + p { margin-top: 8px; }

/* :where() has zero specificity, handy for resets */
:where(ul, ol) { padding-left: 1.25rem; }

/* :has() styles a parent based on its children */
.card:has(img) { padding-top: 0; }
form:has(input:invalid) button[type="submit"] { opacity: 0.5; }

/* Pseudo-elements draw generated content */
.price::before { content: "$"; }
.required::after { content: " *"; color: #dc2626; }

/* border-box makes width include padding and border */
*,
*::before,
*::after {
  box-sizing: border-box;
}

.box {
  /* content size */
  width: 320px;
  height: 180px;

  /* space inside the border */
  padding: 16px 24px;

  /* line around the padding */
  border: 1px solid #d1d5db;
  border-radius: 8px;

  /* space outside the border */
  margin: 24px auto;
}

.card {
  /* top right bottom left */
  margin: 8px 16px 24px 32px;

  /* logical properties follow the writing direction */
  padding-block: 12px;
  padding-inline: 20px;
  border-inline-start: 3px solid #0ea5e9;
}

/* Neighbour spacing without margin collapsing between siblings */
.stack > * + * {
  margin-top: 16px;
}

/* outline does not take up space and does not shift layout */
:focus-visible {
  outline: 2px solid #f59e0b;
  outline-offset: 2px;
}

:root {
  --brand: #1572b6;              /* hex */
  --ink: rgb(17 24 39);          /* rgb, space separated */
  --muted: hsl(215 16% 47%);     /* hue saturation lightness */
  --accent: oklch(62% 0.19 250); /* perceptual lightness and chroma */
}

.alert {
  color: var(--ink);
  background: color-mix(in oklab, var(--brand) 12%, white);
  border-color: rgb(21 114 182 / 0.35); /* alpha as a fraction */
}

/* Named colours and the currentColor keyword */
.link { color: #0f766e; }
.link:visited { color: rebeccapurple; }
.link:hover { text-decoration-color: currentColor; }

body {
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  font-size: 16px;
  line-height: 1.6;
  font-weight: 400;
  letter-spacing: 0.01em;
}

h1 {
  font-size: clamp(2rem, 4vw, 3rem);
  line-height: 1.15;
  text-wrap: balance;
}

p {
  max-width: 65ch;
  hyphens: auto;
}

/* Web font with a fallback shown while it downloads */
@font-face {
  font-family: "Inter";
  src: url("/fonts/inter.woff2") format("woff2");
  font-weight: 100 900;
  font-display: swap;
}

.code {
  font-family: ui-monospace, "SF Mono", Menlo, monospace;
  font-variant-numeric: tabular-nums;
  font-feature-settings: "liga" 0;
}

.title {
  text-transform: uppercase;
  text-decoration: underline wavy #f59e0b 2px;
  text-underline-offset: 4px;
  text-align: center;
}

/* Block fills the line; inline sits in text; inline-block keeps box traits */
.block  { display: block; width: 100%; }
.inline { display: inline; }
.chip   { display: inline-block; padding: 4px 10px; }

/* Hide from layout, or remove entirely */
.invisible { visibility: hidden; }
.gone      { display: none; }

/* Scroll a fixed height instead of overflowing the page */
.feed {
  height: 420px;
  overflow-y: auto;
  overscroll-behavior: contain;
}

/* Reserve space before a remote image loads */
.thumb {
  width: 100%;
  aspect-ratio: 16 / 9;
  object-fit: cover;
}

/* Normal flow with a centred content column */
.page {
  width: min(100% - 32px, 1120px);
  margin-inline: auto;
}

/* Two columns without flex or grid */
.columns {
  column-count: 2;
  column-gap: 32px;
}

/* Floats still wrap text around figures */
.figure {
  float: right;
  margin: 0 0 12px 16px;
}

.prose::after {
  content: "";
  display: block;
  clear: both;
}

.toolbar {
  display: flex;
  flex-direction: row;
  flex-wrap: wrap;
  justify-content: space-between; /* main axis */
  align-items: center;            /* cross axis */
  gap: 12px;
}

/* Push the last item to the far end without an extra wrapper */
.toolbar .spacer {
  margin-left: auto;
}

.card-row {
  display: flex;
  gap: 16px;
}

.card {
  flex: 1 1 240px; /* grow shrink basis */
  min-width: 0;    /* lets long text shrink and truncate */
}

.avatar {
  flex: 0 0 48px;
  align-self: flex-start;
}

/* Order changes paint order, not source or tab order */
.card.featured {
  order: -1;
}

.gallery {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  gap: 20px;
  align-items: start;
}

/* Fixed sidebar plus a fluid main column */
.shell {
  display: grid;
  grid-template-columns: 240px minmax(0, 1fr);
  min-height: 100dvh;
}

.layout {
  display: grid;
  grid-template-areas:
    "header header"
    "sidebar main"
    "footer footer";
  grid-template-columns: 200px 1fr;
  grid-template-rows: auto 1fr auto;
  gap: 16px;
}

.layout > header { grid-area: header; }
.layout > aside  { grid-area: sidebar; }
.layout > main   { grid-area: main; }
.layout > footer { grid-area: footer; }

/* Lines count from 1; -1 is the last line */
.hero {
  grid-column: 1 / -1; /* span every column */
  grid-row: 2 / 4;
}

/* A named item can also be placed by span */
.badge {
  grid-column: 2 / span 2;
  justify-self: end;
  align-self: center;
}

/* Auto-placement skips occupied cells */
.note {
  grid-column: span 2;
  grid-row: span 2;
}

/* Ancestor for absolutely positioned children */
.card {
  position: relative;
}

/* Removed from flow, placed against the nearest positioned ancestor */
.badge {
  position: absolute;
  top: 8px;
  right: 8px;
  z-index: 2;
}

/* Fixed to the viewport */
.to-top {
  position: fixed;
  inset: auto 24px 24px auto;
  z-index: 10;
}

/* Sticks inside its scrolling container, then scrolls away with it */
.section-title {
  position: sticky;
  top: 0;
  z-index: 1;
  background: #ffffff;
  padding-block: 8px;
}

/* inset is shorthand for top, right, bottom and left */
.overlay {
  position: fixed;
  inset: 0;
  background: rgb(15 23 42 / 0.6);
}

/* z-index applies to positioned elements and flex or grid items */
.modal {
  position: fixed;
  z-index: 100;
}

.button {
  background: #1572b6;
  transform: translateY(0);
  transition-property: background-color, transform, box-shadow;
  transition-duration: 180ms;
  transition-timing-function: cubic-bezier(0.2, 0, 0, 1);
  transition-delay: 0ms;
}

.button:hover {
  background: #0f5f99;
  transform: translateY(-2px);
  box-shadow: 0 6px 16px rgb(15 23 42 / 0.25);
}

/* Shorthand: property duration timing delay */
.button:active {
  transition: transform 80ms ease-out 0ms;
}

/* Transitions only run between two computed values */
.fade { opacity: 1; transition: opacity 200ms linear; }
.fade.is-hidden { opacity: 0; }

@keyframes pulse {
  0%, 100% {
    opacity: 1;
    transform: scale(1);
  }
  50% {
    opacity: 0.6;
    transform: scale(0.96);
  }
}

.status-dot {
  animation: pulse 1.8s ease-in-out infinite;
}

/* Respect users who ask for less motion */
@media (prefers-reduced-motion: reduce) {
  .status-dot {
    animation: none;
  }
  * {
    transition-duration: 0.01ms;
    animation-duration: 0.01ms;
  }
}

/* Mobile first: base styles, then widen */
.grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 16px;
}

@media (min-width: 640px) {
  .grid { grid-template-columns: repeat(2, 1fr); }
}

@media (min-width: 1024px) {
  .grid { grid-template-columns: repeat(4, 1fr); }
}

/* Coarse pointers get a larger hit area */
@media (pointer: coarse) {
  .button { min-height: 44px; }
}

/* The card adapts to its own container, not the viewport */
.card-host {
  container-type: inline-size;
  container-name: card;
}

@container card (min-width: 480px) {
  .card {
    display: grid;
    grid-template-columns: 120px 1fr;
  }
}

/* Fluid type without a media query */
h2 {
  font-size: clamp(1.5rem, 1rem + 2vw, 2.5rem);
}

:root {
  --color-brand: #1572b6;
  --color-text: #111827;
  --space-unit: 4px;
  --radius: 10px;
}

.button {
  background: var(--color-brand);
  color: #ffffff;
  padding: calc(var(--space-unit) * 3) calc(var(--space-unit) * 5);
  border-radius: var(--radius);
}

/* Fallback used when the variable is missing */
.muted {
  color: var(--color-muted, #6b7280);
}

/* Variables inherit, so a theme only overrides the values */
.theme-dark {
  --color-bg: #0f172a;
  --color-fg: #e5e7eb;
}

.panel {
  background: var(--color-bg, #ffffff);
  color: var(--color-fg, #111827);
}

/* A variable can hold a whole value list */
.callout {
  --shadow: 0 10px 24px rgb(15 23 42 / 0.18);
  box-shadow: var(--shadow);
}

/* Inline style can override one variable for one element */
.progress {
  --fill: 40%;
  background: linear-gradient(90deg, #1572b6 var(--fill), #e5e7eb var(--fill));
}

/* Center one box in both axes */
.center {
  display: grid;
  place-items: center;
  min-height: 320px;
}

/* Center an absolutely positioned box */
.center-absolute {
  position: absolute;
  inset: 0;
  margin: auto;
  width: 240px;
  height: 120px;
}

/* Single line with an ellipsis */
.truncate {
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
}

/* Multiple lines in current browsers */
.clamp-3 {
  display: -webkit-box;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 3;
  line-clamp: 3;
  overflow: hidden;
}

/* Available to screen readers, invisible on screen */
.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  margin: -1px;
  padding: 0;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
  border: 0;
}

/* Card whose footer stays at the bottom */
.card {
  display: flex;
  flex-direction: column;
  gap: 12px;
  border: 1px solid #e5e7eb;
  border-radius: 12px;
  overflow: hidden;
}

.card img {
  width: 100%;
  aspect-ratio: 16 / 9;
  object-fit: cover;
}

.card .body { padding: 16px; }

.card .footer {
  margin-top: auto;
  padding: 12px 16px;
  border-top: 1px solid #e5e7eb;
}
